// Generated by scripts/gen-content-manifests.mjs. Do not edit.
export const PROJECTS = [{"id":"ai-01","title":"How AI Actually Works","description":"Build a real mental model of how language models predict text, why they sometimes lie, and what tokens actually are.","difficulty":"beginner","category":"foundations","estimated_time":45,"lessons_count":8,"tags":["llm","intuition","tokens","prediction","fundamentals"],"order":1,"cover_image":"","brief":{"tagline":"Build a working mental model of how modern AI does math and prediction.","overview":"This project builds the foundational mental model for how neural networks and large language models actually work, from tokens and weights to next-token prediction. You will leave able to reason about why models behave the way they do instead of treating them as black boxes.","whatYouBuild":["A plain-language explainer of how an LLM turns text into tokens and predicts the next one","A tiny from-scratch next-token predictor (bigram/n-gram) you can run and inspect","A diagram mapping the path from input prompt to output token probabilities"],"milestones":[{"title":"Tokens & vocab","detail":"Understand how raw text is split into tokens and mapped to ids."},{"title":"Weights & layers","detail":"Learn what parameters are and how layers transform a representation."},{"title":"Next-token prediction","detail":"See how a probability distribution over the vocab produces output."},{"title":"Build a mini predictor","detail":"Implement and run a small statistical model that completes text."}],"skills":["tokenization","neural-network basics","probability","model intuition","Python"],"rubric":[{"criterion":"Conceptual accuracy","description":"Explanations correctly describe tokens, weights, and prediction without hand-waving."},{"criterion":"Working demo","description":"The mini predictor runs and produces sensible next-token completions."},{"criterion":"Clarity","description":"A non-expert could follow the explainer and diagram end to end."}],"estimatedHours":3}},{"id":"ai-02","title":"Your First API Call","description":"Send a message to Claude from a Python script and print the reply you get back.","difficulty":"beginner","category":"foundations","estimated_time":60,"lessons_count":8,"tags":["api","json","python","claude","requests"],"order":2,"cover_image":"","brief":{"tagline":"Send your first request to a real LLM and read the response.","overview":"This project gets you hands-on with calling a hosted model API: authentication, request shape, and parsing the response. It is the practical gateway to everything else, turning AI from a website into something you can program against.","whatYouBuild":["A working script that sends a prompt to an LLM API and prints the completion","Secure handling of an API key via environment variables","A small wrapper function with basic error handling and retries"],"milestones":[{"title":"Get a key","detail":"Obtain an API key and store it safely in an environment variable."},{"title":"First call","detail":"Send a single prompt and print the model's text response."},{"title":"Parse the response","detail":"Read tokens used, finish reason, and the message content from the JSON."},{"title":"Harden it","detail":"Wrap the call with try/except, timeouts, and a simple retry."}],"skills":["HTTP/REST","API keys","JSON parsing","environment variables","error handling"],"rubric":[{"criterion":"Successful call","description":"Script reliably returns a valid model completion from a real prompt."},{"criterion":"Secret hygiene","description":"API key is never hardcoded and is loaded from the environment."},{"criterion":"Robustness","description":"Failed or slow requests are handled gracefully rather than crashing."}],"estimatedHours":2}},{"id":"ai-03","title":"Prompt Engineering","description":"Learn the controls (system prompts, temperature, tokens, few-shot, structured output) that turn an LLM from a slot machine into a predictable tool.","difficulty":"beginner","category":"prompting","estimated_time":100,"lessons_count":9,"tags":["prompt-engineering","llm","claude","system-prompts","structured-output"],"order":9,"cover_image":"","brief":{"tagline":"Get better outputs by writing better prompts.","overview":"This project teaches the core levers of prompt design: clear instructions, role and context, examples, and output formatting. You will learn to systematically improve model quality without touching any model internals.","whatYouBuild":["A before/after prompt library showing measurable quality improvements","A reusable prompt template with role, task, constraints, and format sections","A few-shot example set that steers the model toward a desired style"],"milestones":[{"title":"Clear instructions","detail":"Rewrite vague prompts into specific, unambiguous tasks."},{"title":"Role & context","detail":"Add persona and background to ground the model's responses."},{"title":"Few-shot examples","detail":"Provide examples to lock in tone, format, and behavior."},{"title":"Control the output","detail":"Constrain length, format, and structure for predictable results."}],"skills":["prompt design","few-shot learning","instruction tuning","output formatting","iteration"],"rubric":[{"criterion":"Measurable lift","description":"Revised prompts produce clearly better outputs than the originals on the same task."},{"criterion":"Reusability","description":"The template generalizes across multiple tasks with minimal edits."},{"criterion":"Format control","description":"Outputs reliably match the requested structure and length."}],"estimatedHours":3}},{"id":"ai-04","title":"Build a Chatbot","description":"Build a character chatbot that remembers the conversation, stays in persona, and streams its replies token by token.","difficulty":"intermediate","category":"chatbots_agents","estimated_time":120,"lessons_count":8,"tags":["chatbot","message-history","context-window","streaming","persona","anthropic"],"order":12,"cover_image":"","brief":{"tagline":"Build a conversational chatbot that remembers context.","overview":"This project assembles a multi-turn chatbot by managing a running message history and a system prompt. You will understand how conversational memory works and why context windows and message roles matter.","whatYouBuild":["A command-line chatbot that holds a coherent multi-turn conversation","A system prompt that defines the bot's persona and rules","Message-history management that respects the context window"],"milestones":[{"title":"Message roles","detail":"Structure system, user, and assistant messages correctly."},{"title":"Conversation loop","detail":"Read user input, call the model, and print the reply in a loop."},{"title":"Memory","detail":"Append each turn to history so the bot remembers earlier context."},{"title":"Trim the window","detail":"Truncate or summarize history to stay within token limits."}],"skills":["conversation state","system prompts","message roles","context windows","CLI design"],"rubric":[{"criterion":"Coherence","description":"The bot maintains context across many turns without losing the thread."},{"criterion":"Persona","description":"Behavior consistently reflects the configured system prompt."},{"criterion":"Window safety","description":"Long conversations are managed so requests never exceed the context limit."}],"estimatedHours":4}},{"id":"ai-05","title":"Computer Vision Basics","description":"Feed an image to a model, get structured data back, the practical way computers see now.","difficulty":"intermediate","category":"vision_multimodal","estimated_time":120,"lessons_count":8,"tags":["computer-vision","cnn","image-classification","multimodal","claude-api"],"order":14,"cover_image":"","brief":{"tagline":"Make machines see: classify and detect objects in images.","overview":"This project introduces computer vision fundamentals using a pretrained image model to classify and describe images. You will learn how pixels become predictions and how to apply vision models without training from scratch.","whatYouBuild":["An image classifier that labels photos using a pretrained model","A script that runs inference on your own images and reports confidence","A simple comparison of model predictions across a small test set"],"milestones":[{"title":"Load an image","detail":"Read and preprocess an image into the model's expected input format."},{"title":"Run inference","detail":"Pass the image through a pretrained classifier and get labels."},{"title":"Interpret scores","detail":"Read confidence scores and pick the top predictions."},{"title":"Test on real data","detail":"Evaluate the model on your own images and note failure cases."}],"skills":["image preprocessing","pretrained models","inference","classification","confidence scores"],"rubric":[{"criterion":"Correct pipeline","description":"Images are preprocessed and fed to the model in the right shape and format."},{"criterion":"Useful output","description":"Predictions include sensible labels with calibrated confidence values."},{"criterion":"Critical eval","description":"Learner identifies where and why the model misclassifies."}],"estimatedHours":4}},{"id":"ai-06","title":"Embeddings & Semantic Search","description":"Turn words into numbers, measure how close they are, and build a movie recommender that actually gets your taste.","difficulty":"intermediate","category":"rag_search","estimated_time":240,"lessons_count":8,"tags":["embeddings","vectors","cosine-similarity","semantic-search","recommender"],"order":16,"cover_image":"","brief":{"tagline":"Turn text into vectors and search by meaning, not keywords.","overview":"This project teaches embeddings: dense vector representations that capture semantic meaning. You will build a semantic search that finds relevant text even when the words do not match, the cornerstone of modern retrieval.","whatYouBuild":["An embedding pipeline that converts a corpus of text into vectors","A semantic search function ranking results by cosine similarity","A small searchable knowledge base you query in natural language"],"milestones":[{"title":"Generate embeddings","detail":"Convert documents and queries into embedding vectors via an API."},{"title":"Measure similarity","detail":"Compute cosine similarity between query and document vectors."},{"title":"Rank results","detail":"Return the top-k most semantically similar documents."},{"title":"Compare to keywords","detail":"Show where semantic search beats simple keyword matching."}],"skills":["embeddings","cosine similarity","vector math","semantic search","retrieval"],"rubric":[{"criterion":"Relevant retrieval","description":"Queries return semantically appropriate results, including paraphrases."},{"criterion":"Correct similarity","description":"Similarity is computed and normalized correctly for ranking."},{"criterion":"Demonstrated advantage","description":"Learner shows a concrete case where semantic beats keyword search."}],"estimatedHours":5}},{"id":"ai-07","title":"Build a RAG System","description":"Stop your LLM from making things up, bolt a real document search onto it and build a Q&A tool that cites its sources.","difficulty":"advanced","category":"rag_search","estimated_time":180,"lessons_count":8,"tags":["rag","retrieval","embeddings","vector-store","chunking","anthropic-api"],"order":17,"cover_image":"","brief":{"tagline":"Ground an LLM in your own documents with retrieval.","overview":"This project builds a Retrieval-Augmented Generation system that answers questions from a custom document set with citations. You will learn the full pipeline: chunking, embedding, retrieval, and prompt assembly that reduces hallucination.","whatYouBuild":["A document ingestion pipeline that chunks and embeds source material","A retriever that pulls the most relevant chunks for a question","A RAG chat interface that answers with grounded, cited responses"],"milestones":[{"title":"Chunk documents","detail":"Split sources into overlapping, retrievable chunks."},{"title":"Index embeddings","detail":"Embed chunks and store them for fast similarity search."},{"title":"Retrieve & augment","detail":"Fetch top chunks and inject them into the model prompt."},{"title":"Cite sources","detail":"Return answers that reference which chunks they came from."}],"skills":["chunking","embeddings","retrieval","prompt augmentation","grounding","citations"],"rubric":[{"criterion":"Grounded answers","description":"Responses draw from retrieved context rather than model memory."},{"criterion":"Retrieval quality","description":"The correct supporting chunks are surfaced for each question."},{"criterion":"Traceability","description":"Every answer cites the sources it was built from."}],"estimatedHours":6}},{"id":"ai-08","title":"Fine-Tuning & Evals","description":"Stop guessing whether your prompt got better, measure it, and learn when fine-tuning actually beats a good prompt.","difficulty":"advanced","category":"production_ops","estimated_time":180,"lessons_count":8,"tags":["fine-tuning","evals","prompt-engineering","testing","claude-api"],"order":19,"cover_image":"","brief":{"tagline":"Specialize a model and prove it actually got better.","overview":"This project covers fine-tuning a model on task-specific data and, crucially, building evaluations to measure whether it improved. You will learn when fine-tuning is worth it and how to avoid shipping regressions.","whatYouBuild":["A curated and formatted fine-tuning dataset for a specific task","A fine-tuned model checkpoint produced via a training job","An eval harness that scores base vs. fine-tuned on held-out cases"],"milestones":[{"title":"Prepare data","detail":"Collect and format examples into the required training schema."},{"title":"Run fine-tuning","detail":"Launch a fine-tune job and retrieve the resulting model."},{"title":"Build evals","detail":"Define metrics and a held-out test set to score quality."},{"title":"Compare & decide","detail":"Measure base vs. fine-tuned and judge if the gain is worth it."}],"skills":["dataset curation","fine-tuning","evaluation design","metrics","regression testing"],"rubric":[{"criterion":"Clean dataset","description":"Training data is well-formatted, deduplicated, and representative of the task."},{"criterion":"Honest evals","description":"Metrics are run on held-out data and capture real task performance."},{"criterion":"Sound conclusion","description":"Learner correctly judges whether fine-tuning improved results."}],"estimatedHours":7}},{"id":"ai-09","title":"AI Agents & Tool Use","description":"Go beyond chat: learn how language models call tools, loop through reasoning and action, plan multi-step tasks, and where agents break so you can build them safely.","difficulty":"intermediate","category":"chatbots_agents","estimated_time":55,"lessons_count":8,"tags":["agents","tool-use","react","planning","guardrails"],"order":13,"cover_image":"","brief":{"tagline":"Let the model call tools and take real actions.","overview":"This project builds an AI agent that decides when to call external tools, executes them, and incorporates results into its reasoning loop. You will learn the agentic loop that powers assistants which search, compute, and act.","whatYouBuild":["Tool definitions the model can invoke with structured arguments","An agent loop that calls tools, feeds results back, and continues","A working agent that completes a multi-step task using its tools"],"milestones":[{"title":"Define tools","detail":"Describe each tool's name, purpose, and parameter schema for the model."},{"title":"Detect tool calls","detail":"Parse when the model requests a tool and with what arguments."},{"title":"Execute & return","detail":"Run the tool and feed the result back into the conversation."},{"title":"Loop to completion","detail":"Iterate tool calls until the task is fully resolved."}],"skills":["tool use","function calling","agent loops","schema design","orchestration"],"rubric":[{"criterion":"Correct invocation","description":"The model calls the right tool with valid, well-formed arguments."},{"criterion":"Result integration","description":"Tool outputs are fed back and influence the next step correctly."},{"criterion":"Task completion","description":"The agent reliably finishes multi-step tasks without getting stuck."}],"estimatedHours":6}},{"id":"ai-10","title":"Structured Outputs","description":"Stop wrestling with free-form model replies. Learn to force LLMs into clean, parseable JSON using JSON mode, schemas, function calling, and validation so the output plugs straight into real code.","difficulty":"intermediate","category":"prompting","estimated_time":50,"lessons_count":8,"tags":["json","structured-output","function-calling","validation","extraction"],"order":10,"cover_image":"","brief":{"tagline":"Get reliable JSON out of an LLM, every time.","overview":"This project teaches structured outputs: forcing models to return data that matches a schema so it can be consumed by code. You will learn schema definition, validation, and recovery for production-grade reliability.","whatYouBuild":["A JSON schema describing the exact output shape you need","A call that constrains the model to emit schema-valid JSON","A validation and retry layer that rejects and re-requests bad output"],"milestones":[{"title":"Define a schema","detail":"Specify required fields, types, and constraints for the output."},{"title":"Constrain output","detail":"Use structured-output features to force schema-conformant JSON."},{"title":"Validate","detail":"Parse and validate responses against the schema in code."},{"title":"Recover","detail":"Retry or repair when the model returns invalid data."}],"skills":["JSON schema","structured outputs","validation","type safety","parsing"],"rubric":[{"criterion":"Schema conformance","description":"Outputs reliably match the defined schema and parse without errors."},{"criterion":"Validation","description":"Invalid responses are detected programmatically, not assumed valid."},{"criterion":"Resilience","description":"The system recovers from malformed output instead of crashing downstream."}],"estimatedHours":4}},{"id":"ai-11","title":"Multimodal AI: Vision & Images","description":"See how models read images, pull text out of documents, and generate pictures from words. Build the mental model for working with vision and the cost of feeding pixels to a model.","difficulty":"intermediate","category":"vision_multimodal","estimated_time":50,"lessons_count":8,"tags":["multimodal","vision","images","ocr","generation"],"order":15,"cover_image":"","brief":{"tagline":"Work with models that see images and generate them.","overview":"This project explores multimodal AI: passing images into a vision-language model for understanding and generating images from text. You will learn how to combine text and visual inputs in a single application.","whatYouBuild":["A vision call that describes, analyzes, or answers questions about an image","A text-to-image generation request with prompt control","A small app that combines image understanding and generation"],"milestones":[{"title":"Send an image","detail":"Encode and pass an image into a vision-language model."},{"title":"Ask about it","detail":"Get structured answers or descriptions about image content."},{"title":"Generate images","detail":"Produce images from text prompts and control the style."},{"title":"Combine modalities","detail":"Chain understanding and generation into one workflow."}],"skills":["multimodal input","vision-language models","image generation","prompt control","encoding"],"rubric":[{"criterion":"Accurate vision","description":"The model correctly understands and describes the provided images."},{"criterion":"Controlled generation","description":"Generated images reflect the intent and constraints of the prompt."},{"criterion":"Integrated flow","description":"Understanding and generation are combined into a coherent application."}],"estimatedHours":5}},{"id":"ai-12","title":"Vector Databases & Production Search","description":"Learn how vector databases turn embeddings into fast, filterable, production-grade search. Build the pieces of a real retrieval pipeline: ANN indexes, metadata filters, hybrid search, and re-ranking.","difficulty":"advanced","category":"rag_search","estimated_time":55,"lessons_count":8,"tags":["vector-db","ann","retrieval","hybrid-search","reranking","search"],"order":18,"cover_image":"","brief":{"tagline":"Scale semantic search to millions of vectors in production.","overview":"This project moves embeddings into a real vector database with indexing, metadata filtering, and persistence. You will learn the infrastructure that makes retrieval fast and reliable at production scale.","whatYouBuild":["A populated vector database with an ANN index over your embeddings","Filtered queries combining semantic search with metadata constraints","A benchmark comparing recall and latency across index settings"],"milestones":[{"title":"Stand up a store","detail":"Initialize a vector database and define the collection schema."},{"title":"Index at scale","detail":"Insert embeddings with an approximate-nearest-neighbor index."},{"title":"Filter & query","detail":"Combine vector search with metadata filters for precise results."},{"title":"Benchmark","detail":"Measure latency and recall and tune index parameters."}],"skills":["vector databases","ANN indexing","metadata filtering","scaling","benchmarking"],"rubric":[{"criterion":"Correct indexing","description":"Vectors are stored and indexed so queries return relevant results quickly."},{"criterion":"Hybrid queries","description":"Semantic search and metadata filters combine correctly in one query."},{"criterion":"Performance awareness","description":"Learner measures and reasons about the recall/latency trade-off."}],"estimatedHours":7}},{"id":"ai-13","title":"Streaming, Latency & Caching","description":"Make AI apps feel fast: stream tokens as they arrive, cache repeated prompts, batch work for throughput, and measure the latency numbers that actually matter.","difficulty":"advanced","category":"production_ops","estimated_time":50,"lessons_count":8,"tags":["streaming","latency","caching","throughput","performance","sse"],"order":20,"cover_image":"","brief":{"tagline":"Make LLM apps feel instant with streaming and caching.","overview":"This project tackles production performance: streaming tokens for perceived speed, caching to cut cost and latency, and measuring the trade-offs. You will learn to make AI features feel responsive under real load.","whatYouBuild":["A streaming response handler that renders tokens as they arrive","A caching layer that serves repeated or similar requests instantly","A latency dashboard tracking time-to-first-token and total time"],"milestones":[{"title":"Stream tokens","detail":"Consume a streaming API and display output incrementally."},{"title":"Measure latency","detail":"Track time-to-first-token and end-to-end response time."},{"title":"Add caching","detail":"Cache responses to avoid recomputing identical requests."},{"title":"Tune trade-offs","detail":"Balance freshness, cost, and speed across the system."}],"skills":["streaming","caching","latency optimization","performance measurement","cost control"],"rubric":[{"criterion":"Smooth streaming","description":"Output renders progressively with low time-to-first-token."},{"criterion":"Effective cache","description":"Repeated requests are served from cache with correct invalidation."},{"criterion":"Measured impact","description":"Learner quantifies the latency and cost improvements achieved."}],"estimatedHours":6}},{"id":"ai-14","title":"Guardrails & Safety","description":"Learn how AI systems get attacked through prompts and how to defend them with input filtering, output checks, PII handling, jailbreak resistance, and content moderation.","difficulty":"advanced","category":"production_ops","estimated_time":50,"lessons_count":8,"tags":["safety","security","prompt-injection","moderation","guardrails","pii"],"order":21,"cover_image":"","brief":{"tagline":"Keep AI safe, on-policy, and resistant to abuse.","overview":"This project builds guardrails around an LLM: input and output filtering, prompt-injection defense, and policy enforcement. You will learn to ship AI features that resist misuse and stay within defined boundaries.","whatYouBuild":["Input validation that blocks unsafe or out-of-scope requests","Output moderation that screens responses before they reach users","Prompt-injection defenses protecting system instructions"],"milestones":[{"title":"Filter inputs","detail":"Detect and block disallowed or malicious user requests."},{"title":"Moderate outputs","detail":"Screen model responses against safety and policy rules."},{"title":"Resist injection","detail":"Harden prompts so user content cannot override instructions."},{"title":"Enforce policy","detail":"Apply consistent rules and log violations for review."}],"skills":["content moderation","prompt-injection defense","input validation","safety policy","logging"],"rubric":[{"criterion":"Input safety","description":"Unsafe or out-of-scope requests are reliably caught before model calls."},{"criterion":"Output safety","description":"Policy-violating responses are blocked or rewritten before delivery."},{"criterion":"Injection resistance","description":"Adversarial prompts fail to override system instructions."}],"estimatedHours":6}},{"id":"ai-15","title":"Advanced Prompting Patterns","description":"Move past one-shot prompts into reliable patterns: chain of thought, few-shot, self-consistency, ReAct, and decomposition. Each pattern is a tool for squeezing more correctness out of the same model.","difficulty":"intermediate","category":"prompting","estimated_time":50,"lessons_count":8,"tags":["prompting","chain-of-thought","few-shot","react","reasoning"],"order":11,"cover_image":"","brief":{"tagline":"Handle harder tasks with chain-of-thought and related patterns.","overview":"This project covers advanced prompting patterns: chain-of-thought, self-consistency, ReAct, and decomposition. You will learn techniques that improve reasoning quality on complex, multi-step problems.","whatYouBuild":["A chain-of-thought prompt that improves multi-step reasoning","A self-consistency setup that samples and votes on answers","A ReAct-style prompt interleaving reasoning and actions"],"milestones":[{"title":"Chain-of-thought","detail":"Prompt the model to reason step by step before answering."},{"title":"Decompose tasks","detail":"Break complex problems into ordered sub-prompts."},{"title":"Self-consistency","detail":"Sample multiple reasoning paths and select the consensus answer."},{"title":"ReAct pattern","detail":"Interleave thought and action to solve interactive tasks."}],"skills":["chain-of-thought","task decomposition","self-consistency","ReAct","reasoning"],"rubric":[{"criterion":"Reasoning gain","description":"Advanced patterns measurably outperform naive prompting on hard tasks."},{"criterion":"Correct pattern fit","description":"Learner selects the appropriate pattern for each problem type."},{"criterion":"Reliability","description":"Techniques like self-consistency reduce variance in final answers."}],"estimatedHours":5}},{"id":"ai-16","title":"Deploying & Monitoring LLM Apps","description":"Take an LLM prototype from a notebook to a reliable production service: deploy it, trace every call, gate releases with evals, watch the cost, and survive failures with fallbacks.","difficulty":"advanced","category":"production_ops","estimated_time":55,"lessons_count":8,"tags":["deployment","observability","evals","cost","reliability","production"],"order":22,"cover_image":"","brief":{"tagline":"Ship and operate an LLM app users can depend on.","overview":"This project takes an AI feature to production: deployment, logging, monitoring, cost tracking, and alerting on quality drift. You will learn the operational discipline that separates a demo from a real product.","whatYouBuild":["A deployed API endpoint serving an LLM-backed feature","Structured logging of prompts, responses, latency, and cost","Monitoring with alerts on errors, cost spikes, and quality drift"],"milestones":[{"title":"Deploy","detail":"Package and deploy the LLM app behind a stable endpoint."},{"title":"Log everything","detail":"Capture requests, responses, tokens, and latency for each call."},{"title":"Monitor","detail":"Build dashboards for cost, error rate, and response quality."},{"title":"Alert","detail":"Trigger alerts on failures, cost spikes, and drift."}],"skills":["deployment","observability","logging","cost tracking","monitoring","alerting"],"rubric":[{"criterion":"Reliable deploy","description":"The feature is reachable, stable, and configured for production use."},{"criterion":"Full observability","description":"Logs and metrics make every request traceable and debuggable."},{"criterion":"Proactive alerts","description":"Operational issues surface via alerts before users are widely affected."}],"estimatedHours":7}},{"id":"ai-17","title":"Chat Roles & Messages","description":"Learn how a chat request is really an ordered list of role-tagged messages, and how apps assemble that list to drive a conversation.","difficulty":"beginner","category":"foundations","estimated_time":90,"lessons_count":8,"tags":["messages","system-prompt","roles","conversation","fundamentals"],"order":3,"cover_image":"","brief":{"tagline":"See chat for what it really is: an ordered list of role-tagged messages.","overview":"This project reveals the structure behind every chat interface: a request is not a paragraph but an ordered list of messages, each tagged with a role (system, user, or assistant) and content. You will learn how system prompts set behavior, how multi-turn memory is really the app resending the full history each turn, and how to assemble the message array in code, the pattern every chatbot is built on.","whatYouBuild":["A transcript printer that walks a list of role-tagged message dicts and labels each speaker","Two system prompts that visibly reshape the same assistant's persona and output format","A growing conversation history that appends user and assistant turns and resends the whole list each turn","A reusable build_chat helper that assembles an ordered message array from a system prompt and turns"],"milestones":[{"title":"The message list","detail":"Model a chat request as an ordered list of {role, content} dicts the model continues."},{"title":"System prompts","detail":"Place a system message first to set persona, rules, and output format for the whole chat."},{"title":"Multi-turn memory","detail":"Append each user and assistant turn to history and resend the full transcript every turn."},{"title":"Build the array","detail":"Assemble and grow the message array in code, keeping it flat and in order."}],"skills":["message roles","system prompts","conversation history","statelessness","Python lists & dicts"],"rubric":[{"criterion":"Correct structure","description":"Messages are well-formed role/content dicts assembled as a flat, ordered list."},{"criterion":"Behavior control","description":"A system prompt is placed first and demonstrably changes the assistant's persona and format."},{"criterion":"History handling","description":"Both user and assistant turns are appended in order and the full list is resent each turn."}],"estimatedHours":3}},{"id":"ai-18","title":"The Context Window","description":"Understand the model's working memory: the token budget that holds your system prompt, chat history, message, and its answer, and what to do when it runs out.","difficulty":"beginner","category":"foundations","estimated_time":45,"lessons_count":8,"tags":["context-window","tokens","limits","memory","fundamentals"],"order":4,"cover_image":"","brief":{"tagline":"Understand the model's working memory: the token budget behind every request.","overview":"This project builds a precise mental model of the context window: the fixed token budget a model can consider in one request, shared between your input and its output. You will learn exactly what consumes that budget, what happens when you exceed it, and the strategies for keeping the right information in view so your AI features stay coherent, cheap, and reliable.","whatYouBuild":["A token-budget calculator that shows how much room is left for the answer after the system prompt, history, and message","A truncation simulator that drops the oldest turns until a conversation fits the window","A context manager that trims and summarizes history to keep long sessions inside the limit"],"milestones":[{"title":"Define the window","detail":"Understand the window as a shared token ceiling for input plus output."},{"title":"Account the budget","detail":"Tally how the system prompt, chat history, message, and reserved answer space all spend from it."},{"title":"Handle overflow","detail":"See how exceeding the window causes hard errors or silent oldest-first truncation."},{"title":"Manage context","detail":"Trim, summarize, and filter history to keep what matters inside the limit."}],"skills":["context windows","token budgeting","truncation","history summarization","Python"],"rubric":[{"criterion":"Conceptual accuracy","description":"Correctly explains that the window is a shared input-plus-output token ceiling, not long-term memory."},{"criterion":"Budget reasoning","description":"Accurately accounts for every part of a request and computes the room left for history or the answer."},{"criterion":"Management strategy","description":"Applies trimming, summarization, and relevance filtering to keep long sessions within the limit."}],"estimatedHours":3}},{"id":"ai-19","title":"Temperature & Sampling","description":"Learn why the same prompt gives different answers, and how temperature, top-p, and top-k let you dial a model from precise to playful.","difficulty":"beginner","category":"foundations","estimated_time":45,"lessons_count":8,"tags":["temperature","sampling","top-p","randomness","fundamentals"],"order":5,"cover_image":"","brief":{"tagline":"Dial a model from precise to playful by controlling how it samples.","overview":"This project explains why the same prompt gives different answers and teaches the settings that govern an LLM's randomness: temperature, top-p, and top-k. You will leave able to deliberately choose settings that make a model deterministic for facts and code, or more varied for brainstorming and writing, instead of accepting whatever defaults you're handed.","whatYouBuild":["A weighted-sampling simulator that draws next tokens from a probability distribution","A temperature-scaled softmax that visibly sharpens or flattens the same logits","A working top-k and top-p (nucleus) truncation implementation with renormalization","A task-to-settings recommender that maps goals onto temperature and top-p values"],"milestones":[{"title":"Sampling vs greedy","detail":"See why a model samples from a distribution instead of always taking the top token."},{"title":"Temperature dial","detail":"Reshape logits with temperature and watch the distribution sharpen or flatten."},{"title":"Top-p and top-k","detail":"Truncate the candidate pool by fixed count or cumulative probability, then renormalize."},{"title":"Match settings to task","detail":"Pick temperature and top-p based on whether a task has one right answer or many."}],"skills":["sampling","temperature","softmax","nucleus sampling (top-p)","Python"],"rubric":[{"criterion":"Conceptual accuracy","description":"Correctly explains distributions, temperature scaling, and the difference between top-k and top-p."},{"criterion":"Working demos","description":"The sampling, softmax, and truncation scripts run and produce the expected outputs."},{"criterion":"Applied judgment","description":"Learner chooses sensible settings for convergent vs divergent tasks and justifies why."}],"estimatedHours":3}},{"id":"ai-20","title":"Reading Model Outputs","description":"Learn to read what a model API hands back: where the text lives, why generation stopped, and how many tokens it cost.","difficulty":"beginner","category":"foundations","estimated_time":45,"lessons_count":8,"tags":["response","finish-reason","usage","stop-sequence","fundamentals"],"order":6,"cover_image":"","brief":{"tagline":"Read an API response and understand what the model handed back.","overview":"This project teaches you to parse a model API's response object end to end: where the generated text is nested, why generation stopped, and how many tokens the call spent. You will leave able to pull the answer out cleanly, detect truncated or blocked output, track cost from the usage block, and bound generation with stop sequences.","whatYouBuild":["A parser that reaches the content text through the choices → message → content path","A finish-reason check that flags truncated ('length') and blocked outputs before you ship them","A cost calculator that reads the usage block and applies separate input/output token rates","A stop-sequence simulator that cuts generation at a boundary you define"],"milestones":[{"title":"Reach the content","detail":"Index choices[0] and read message.content out of the nested response."},{"title":"Read the finish reason","detail":"Tell a natural stop from a length cut-off, stop sequence, or content filter."},{"title":"Account for tokens","detail":"Pull prompt, completion, and total tokens from usage and turn them into cost."},{"title":"Bound the output","detail":"Use a stop sequence to halt generation cleanly at a defined marker."}],"skills":["response parsing","JSON/dict navigation","finish reasons","token accounting","stop sequences"],"rubric":[{"criterion":"Correct extraction","description":"Code reliably reaches the content string through the choices/message/content path."},{"criterion":"Robust handling","description":"Truncated and blocked responses are detected via finish_reason rather than shipped blindly."},{"criterion":"Cost awareness","description":"The usage block is read correctly and converted to an accurate per-call cost."}],"estimatedHours":3}},{"id":"ai-21","title":"Cost & Token Budgeting","description":"Learn how LLM billing actually works so you can estimate, predict, and cut the cost of every API call.","difficulty":"beginner","category":"foundations","estimated_time":45,"lessons_count":8,"tags":["cost","tokens","pricing","budgeting","fundamentals"],"order":7,"cover_image":"","brief":{"tagline":"Estimate, predict, and slash the cost of every LLM call.","overview":"This project builds a working intuition for how language model billing actually works, per-token pricing with input and output charged separately, why output dominates, and how chat history compounds cost by being resent every turn. You will move from being surprised by an invoice to estimating any feature's cost before you ship it and knowing exactly which levers cut the bill.","whatYouBuild":["A per-call cost calculator that prices input and output tokens separately","A pre-launch estimator that turns a prompt into expected tokens, dollars, and a daily bill at scale","A history-cost simulator showing how resent transcripts compound, plus a trimming/capping tool that measures the savings"],"milestones":[{"title":"How pricing works","detail":"Understand per-token billing with separate input and output rates quoted per million."},{"title":"Estimate before you call","detail":"Approximate tokens from text (chars/4) and compute expected cost ahead of time."},{"title":"Find the cost drivers","detail":"See why long outputs and compounding chat history dominate real bills."},{"title":"Cut the bill","detail":"Apply trimming, output caps, prompt caching, and model choice to lower spend."}],"skills":["token estimation","cost modeling","pricing math","context management","Python"],"rubric":[{"criterion":"Accurate cost math","description":"Calculations correctly price input and output tokens separately and format money precisely."},{"criterion":"Sound estimation","description":"Learner estimates per-call and at-scale cost before making a call."},{"criterion":"Effective optimization","description":"Learner identifies the dominant cost drivers and applies the right levers to reduce them."}],"estimatedHours":3}},{"id":"ai-22","title":"Choosing the Right Model","description":"Learn to pick the right model tier for each task by trading off cost, latency, and quality instead of always reaching for the biggest one.","difficulty":"beginner","category":"foundations","estimated_time":45,"lessons_count":8,"tags":["model-selection","latency","cost","quality","fundamentals"],"order":8,"cover_image":"","brief":{"tagline":"Stop reaching for the biggest model and learn to pick the right tier for each task.","overview":"This project builds the practical judgment behind model selection: how providers ship families of small, medium, and large tiers, how cost, latency, and quality trade against each other, how to route easy tasks to cheap fast models and hard tasks to large ones, and how to choose between candidates with a tiny eval set. You will leave able to defend a model choice with evidence and switch models by changing a single id.","whatYouBuild":["A tier 'menu' that scores small, medium, and large models on cost, latency, and quality","A task router that maps each request to the cheapest tier that can still do it well","A tiny eval harness that runs candidate models on known tasks and picks a winner"],"milestones":[{"title":"Tiers, not 'the AI'","detail":"See a model family as a menu of small/medium/large tiers with different trade-offs."},{"title":"The three trade-offs","detail":"Balance cost, latency, and quality, optimizing two at the expense of the third."},{"title":"Route by difficulty","detail":"Send simple classification/extraction to small tiers and hard reasoning to large ones."},{"title":"Measure and switch","detail":"Build an eval set, compare candidates, and keep code model-agnostic for one-line swaps."}],"skills":["model selection","cost/latency/quality trade-offs","task routing","evaluation","Python"],"rubric":[{"criterion":"Right-sized choices","description":"Tasks are matched to the cheapest tier that meets quality needs, not the biggest by default."},{"criterion":"Trade-off reasoning","description":"Decisions explicitly weigh cost, latency, and quality against the use case."},{"criterion":"Evidence over vibes","description":"Model choices are backed by a runnable eval comparing candidates on real tasks."}],"estimatedHours":3}},{"id":"csp-crd","title":"Creative Development","description":"Explores how programs are designed, developed, and refined through collaboration, planning, prototyping, testing, documentation, and systematic error correction.","difficulty":"beginner","category":"apcsp","order":101,"track":"apcsp","unit":"Big Idea 1, Creative Development","tags":["collaboration","program design","errors"],"brief":null},{"id":"csp-dat","title":"Data","description":"Explores how computers represent, store, compress, and analyze data using binary, number bases, and how information and bias are extracted from large datasets.","difficulty":"beginner","category":"apcsp","order":102,"track":"apcsp","unit":"Big Idea 2, Data","tags":["binary","compression","data analysis"],"brief":null},{"id":"csp-aap1","title":"Variables, Lists & Procedures","description":"Big Idea 3 introduction: store data in variables, build expressions and strings, group values in lists, and package reusable logic into procedures with parameters, return values, and scope.","difficulty":"beginner","category":"apcsp","order":103,"track":"apcsp","unit":"Big Idea 3, Algorithms & Programming I","tags":["variables","lists","procedures"],"brief":null},{"id":"csp-aap2","title":"Algorithms, Iteration & Simulation","description":"Build the control-flow core of Big Idea 3: Boolean logic, conditionals, loops, list traversals, searching, simulation, and why some problems are hard or impossible to solve.","difficulty":"beginner","category":"apcsp","order":104,"track":"apcsp","unit":"Big Idea 3, Algorithms & Programming II","tags":["iteration","searching","simulation"],"brief":null},{"id":"csp-csn","title":"Computer Systems & Networks","description":"Trace how the internet moves data through packets, routing, and protocols, why redundancy makes it fault tolerant, and how parallel and distributed computing speed up work.","difficulty":"beginner","category":"apcsp","order":105,"track":"apcsp","unit":"Big Idea 4, Computer Systems & Networks","tags":["the internet","packets & routing","parallel computing"],"brief":null},{"id":"csp-ioc","title":"Impact of Computing","description":"Big Idea 5 explores how computing innovations create beneficial and harmful effects, raise issues of access and bias, and demand legal, ethical, and safe behavior.","difficulty":"beginner","category":"apcsp","order":106,"track":"apcsp","unit":"Big Idea 5, Impact of Computing","tags":["effects","access","ethics"],"brief":null},{"id":"csp-lab","title":"Programming Lab: Python for CSP","description":"A hands-on Python lab that reinforces the Algorithms and Programming big idea with real coding practice, from variables and loops to procedures, search, and a small simulation.","difficulty":"beginner","category":"apcsp","order":102.5,"track":"apcsp","unit":"Programming Lab","tags":["python","practice","algorithms","coding"],"brief":null},{"id":"csa-01","title":"Primitive Types","description":"Master Java's primitive types, literals, arithmetic, casting, operator precedence, and console output to build a rock-solid foundation for AP Computer Science A.","difficulty":"intermediate","category":"apcsa","order":201,"track":"apcsa","unit":"Unit 1, Primitive Types","tags":["java","primitives","arithmetic"],"brief":null},{"id":"csa-02","title":"Using Objects","description":"Create and use objects, call methods on String, Math, and wrapper classes, and reason about how references differ from primitive values in Java.","difficulty":"intermediate","category":"apcsa","order":202,"track":"apcsa","unit":"Unit 2, Using Objects","tags":["java","objects","strings"],"brief":null},{"id":"csa-03","title":"Boolean Expressions & if Statements","description":"Master relational and logical operators, conditional control flow, nested and compound boolean logic, short-circuit evaluation, and De Morgan's Law in Java for the AP CSA exam.","difficulty":"intermediate","category":"apcsa","order":203,"track":"apcsa","unit":"Unit 3, Boolean Expressions & if","tags":["java","booleans","conditionals"],"brief":null},{"id":"csa-04","title":"Iteration","description":"Master while and for loops, loop boundaries, nested loops, String traversals, and informal runtime comparison in the AP CSA Java subset.","difficulty":"intermediate","category":"apcsa","order":204,"track":"apcsa","unit":"Unit 4, Iteration","tags":["while/for loops","nested loops","loop analysis"],"brief":null},{"id":"csa-05","title":"Writing Classes","description":"Design your own Java classes from scratch using instance variables, constructors, accessor and mutator methods, the this keyword, encapsulation, static members, toString, and method decomposition.","difficulty":"intermediate","category":"apcsa","order":205,"track":"apcsa","unit":"Unit 5, Writing Classes","tags":["instance vars","constructors","encapsulation"],"brief":null},{"id":"csa-06","title":"Array","description":"Master one-dimensional arrays in Java: declaration, indexing, traversal, and the standard algorithms tested on the AP CS A exam.","difficulty":"intermediate","category":"apcsa","order":206,"track":"apcsa","unit":"Unit 6, Array","tags":["arrays","java","apcsa"],"brief":null},{"id":"csa-07","title":"ArrayList","description":"Master Java's dynamic ArrayList<E>: adding, accessing, traversing, removing, autoboxing, and running standard algorithms for the AP CSA exam.","difficulty":"intermediate","category":"apcsa","order":207,"track":"apcsa","unit":"Unit 7, ArrayList","tags":["arraylist","java","collections"],"brief":null},{"id":"csa-08","title":"2D Array","description":"Covers two-dimensional array declaration and initialization, row-major order, nested-loop traversal, enhanced-for iteration, and standard grid algorithms in the AP CSA Java subset.","difficulty":"intermediate","category":"apcsa","order":208,"track":"apcsa","unit":"Unit 8, 2D Array","tags":["2D arrays","nested loops","grids"],"brief":null},{"id":"csa-09","title":"Inheritance","description":"Master class inheritance in Java by building hierarchies with extends, super, method overriding, polymorphism, and the universal Object class.","difficulty":"intermediate","category":"apcsa","order":209,"track":"apcsa","unit":"Unit 9, Inheritance","tags":["java","oop","inheritance"],"brief":null},{"id":"csa-10","title":"Recursion","description":"Master recursive thinking in Java, base cases, the call stack, tracing, and recursive search and sort.","difficulty":"intermediate","category":"apcsa","order":210,"track":"apcsa","unit":"Unit 10, Recursion","tags":["recursion","java","apcsa"],"brief":null},{"id":"csa-11","title":"Exam Workshop: FRQ Strategies","description":"Master the four AP CSA free-response question types with rubric thinking, worked Java examples, tracing practice, and a full timed walkthrough so you earn every point you can.","difficulty":"intermediate","category":"apcsa","order":211,"track":"apcsa","unit":"Exam Workshop","tags":["exam","frq","java","practice"],"brief":null},{"id":"prod-00","title":"How to Build with AI: The Playbook","description":"A warm-up before the build track. Learn the loop every AI product follows, set up Python and your API key once, pick the starter tech stack the projects use, and see how each guide is laid out. By the end nothing in the track feels unfamiliar.","difficulty":"beginner","category":"foundations","estimated_time":75,"lessons_count":7,"tags":["setup","workflow","python","api-key","tech-stack","getting-started"],"order":100,"cover_image":"","track":"ai","kind":"product","optional":true,"brief":null},{"id":"prod-01","title":"AI Text Summarizer","description":"Build a command-line tool that turns any article or pasted text into a tight, faithful summary. You'll learn the summarize prompt, how to control length and format, how to chunk text that's too long to send at once, and a map-reduce pass for very long documents.","difficulty":"beginner","category":"foundations","estimated_time":120,"lessons_count":8,"tags":["summarization","prompting","chunking","map-reduce","python","anthropic"],"order":101,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-02","title":"Smart Reply Generator","description":"Build a tool that drafts email and message replies in your own voice. Feed it an incoming message and a few of your past replies. It measures how you write, produces a handful of drafts, and returns the one that sounds most like you.","difficulty":"beginner","category":"foundations","estimated_time":120,"lessons_count":8,"tags":["smart-reply","tone-matching","few-shot","email","drafting","prompting"],"order":102,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-03","title":"Flashcard Maker","description":"Build a command-line tool that turns a block of messy study notes into a clean deck of question/answer flashcards. It extracts facts with the model, dedupes them, and exports the deck to a CSV file that imports straight into Anki.","difficulty":"beginner","category":"foundations","estimated_time":120,"lessons_count":8,"tags":["flashcards","extraction","json-output","dedup","csv-export","anki"],"order":103,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-04","title":"Resume Bullet Booster","description":"A command-line tool that rewrites plain task descriptions into strong, quantified resume bullets. You build the rewrite prompt, enforce action-verb openings and length limits, then batch a whole list of tasks into polished bullets you can paste straight into a resume.","difficulty":"beginner","category":"foundations","estimated_time":120,"lessons_count":8,"tags":["resume","prompting","rewrite","action-verbs","validation","anthropic"],"order":104,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-05","title":"Tone Rewriter","description":"Build a tool that takes a block of text and rewrites it in a tone you pick, formal, casual, or friendly, without changing what it says. Along the way you'll write a system-prompt template, build reusable tone presets, and work out how to hold the meaning steady while the style shifts.","difficulty":"beginner","category":"prompting","estimated_time":120,"lessons_count":8,"tags":["tone-rewriter","system-prompt","templating","presets","style-transfer","prompting"],"order":105,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-06","title":"Structured JSON Extractor","description":"Build a tool that reads messy free text (a signature block, a pasted receipt, a paragraph of notes) and returns the same strict JSON every time. You'll extract contacts and invoices, parse and repair the model's reply, and check that every required field is present before you trust it.","difficulty":"intermediate","category":"prompting","estimated_time":120,"lessons_count":8,"tags":["json","extraction","schema","validation","parsing","prompting"],"order":106,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-07","title":"Meeting Notes to Action Items","description":"Turn a raw meeting transcript into a clean list of action items, each with an owner and a due date, then group them by person. You'll build the extraction prompt, force reliable JSON output, and harden it against messy real-world transcripts.","difficulty":"intermediate","category":"prompting","estimated_time":120,"lessons_count":8,"tags":["prompting","extraction","structured-output","json","meeting-notes","action-items"],"order":107,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-08","title":"Persona Chatbot","description":"Build a stateful character chatbot that keeps the whole conversation in memory and stays in character while it streams replies token by token. By lesson 8 you have a runnable chat session that trims its own history to stay in budget and survives bad input and flaky network calls.","difficulty":"intermediate","category":"chatbots_agents","estimated_time":120,"lessons_count":8,"tags":["chatbot","message-history","persona","streaming","context-window","anthropic"],"order":108,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-09","title":"FAQ Support Bot","description":"Build a support bot that answers only from a small FAQ you provide. It refuses anything the docs don't cover and points back to the exact line it used. You'll stuff a doc into context, ground every answer in it, then guard the whole thing against runaway cost and bad output.","difficulty":"intermediate","category":"chatbots_agents","estimated_time":130,"lessons_count":8,"tags":["rag","grounding","faq-bot","citations","prompting","anthropic"],"order":109,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-10","title":"Tool-Using Agent","description":"Build an agent that acts instead of only talking. It runs a calculator, checks the weather, and looks up facts by calling real functions and reading their results back into its own answer. You will learn function calling from end to end: defining a tool schema, then running the execute-and-respond loop without letting it crash or run away.","difficulty":"intermediate","category":"chatbots_agents","estimated_time":130,"lessons_count":8,"tags":["tool-use","function-calling","agents","json-schema","anthropic","python"],"order":110,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-11","title":"Multi-Step Task Agent","description":"Build an agent that turns a goal into an ordered plan, runs each step with the right tool, and stops itself when the work is done. You'll write a tool registry, pass data from one step into the next, track state as the plan runs, and defend the loop against dependency cycles, tool failures, and runaway repetition.","difficulty":"advanced","category":"chatbots_agents","estimated_time":130,"lessons_count":8,"tags":["agents","planning","tool-use","task-decomposition","state-tracking","stopping-conditions"],"order":111,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-12","title":"Caption & Alt-Text Generator","description":"Build a tool that turns any image into two outputs at once: a caption written for sighted readers and alt text written for screen readers. You'll learn how vision models take image input, how to prompt for two jobs from one picture, and how to keep the output inside real accessibility rules.","difficulty":"intermediate","category":"vision_multimodal","estimated_time":120,"lessons_count":8,"tags":["vision","multimodal","captioning","alt-text","accessibility","image-encoding"],"order":112,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-13","title":"Receipt Scanner","description":"Turn a photo of a receipt into structured expense JSON: merchant, date, line items, and totals. You'll teach the model to read an image, pin its answer to a strict schema, and check the arithmetic before you trust a single number it hands back.","difficulty":"intermediate","category":"vision_multimodal","estimated_time":130,"lessons_count":8,"tags":["vision","ocr","json-extraction","validation","expenses","multimodal"],"order":113,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-14","title":"Screenshot Describer","description":"Build a tool that turns a UI screenshot into a structured description or matching starter HTML you can build on. You send an image to the model, prompt it for a structured layout, turn that structure into markup and layout CSS, then guard the pipeline against bad JSON and oversized images.","difficulty":"intermediate","category":"vision_multimodal","estimated_time":130,"lessons_count":8,"tags":["vision","image-input","multimodal","ui-parsing","html-generation","prompting"],"order":114,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-15","title":"Chat With Your PDF","description":"Build an app that reads a PDF, breaks it into searchable chunks, and answers questions using only what's actually in the document. Along the way you'll write the chunker, the embedding calls, cosine-similarity retrieval, and the guards that keep the model from making things up when the document stays silent.","difficulty":"intermediate","category":"rag_search","estimated_time":130,"lessons_count":8,"tags":["rag","embeddings","retrieval","chunking","vector-search","anthropic"],"order":115,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-16","title":"Semantic Search Engine","description":"Build a search tool that finds results by meaning instead of matching keywords. By lesson 8 you have a working engine that embeds a corpus, ranks it by cosine similarity, and returns the top-k matches with their scores.","difficulty":"intermediate","category":"rag_search","estimated_time":130,"lessons_count":8,"tags":["embeddings","semantic-search","cosine-similarity","vector-search","rag","voyage-ai"],"order":116,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-17","title":"Personal Notes Brain","description":"Build a question-answering assistant that reads your own notes and cites exactly where each answer came from. You index your notes into searchable chunks, retrieve the right ones for a question, and write a footnoted answer backed by real sources instead of a guess.","difficulty":"advanced","category":"rag_search","estimated_time":135,"lessons_count":8,"tags":["rag","embeddings","citations","retrieval","semantic-search","grounding"],"order":117,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-18","title":"Codebase Assistant","description":"Build a tool that reads a code repository, splits it into function-sized chunks, and pulls the pieces most relevant to a question using retrieval built for code rather than prose. Every answer cites the exact file and line range it came from, and the tool says when the codebase has no answer instead of guessing.","difficulty":"advanced","category":"rag_search","estimated_time":150,"lessons_count":8,"tags":["rag","code-search","embeddings","chunking","retrieval","citations"],"order":118,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-19","title":"Guardrails & Moderation Filter","description":"Build a reusable safety layer that screens every AI feature's input and output before it reaches a person. It stops harmful requests and unsafe replies, and it catches prompt-injection attempts hidden inside documents. You'll wire a blocklist, a classifier-based moderation gate, an injection detector, and a config-driven policy into one drop-in guard() function.","difficulty":"advanced","category":"production_ops","estimated_time":135,"lessons_count":8,"tags":["guardrails","moderation","prompt-injection","policy-config","safety","anthropic"],"order":119,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-20","title":"Streaming Writing Assistant","description":"Build a small web app that streams AI-generated writing token by token, so a user watches an essay outline or email draft appear live instead of staring at a spinner. You'll wire a minimal backend endpoint that streams over Server-Sent Events and a front end that renders tokens as they arrive. Along the way you'll add the buffering that survives a choppy network and the budget guard that stops a runaway generation from quietly running up a bill.","difficulty":"advanced","category":"production_ops","estimated_time":135,"lessons_count":8,"tags":["streaming","server-sent-events","fastapi","web-app","backend","frontend"],"order":120,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-21","title":"AI Evals Harness","description":"Build a harness that runs a test set of inputs through an AI feature and grades each result automatically, using rule-based checks and an LLM as judge. By the end you have a script that scores pass rates by category, catches regressions against a baseline, and prints a report you can wire into CI.","difficulty":"advanced","category":"production_ops","estimated_time":135,"lessons_count":8,"tags":["evals","test-set","llm-as-judge","grading","regression-testing","production-ops"],"order":121,"cover_image":"","track":"ai","kind":"product","brief":null},{"id":"prod-22","title":"Ship & Monitor an LLM App (Capstone)","description":"The capstone build. You take your model-calling code, wrap it in a real HTTP endpoint, deploy it, and add structured logging, per-call cost tracking, and a usage dashboard. By the end you have a live LLM service that logs what it does, catches its own failures, and refuses to blow past a budget. Not a script that worked once on your laptop.","difficulty":"advanced","category":"production_ops","estimated_time":140,"lessons_count":8,"tags":["deployment","observability","cost-tracking","dashboards","fastapi","capstone"],"order":122,"cover_image":"","track":"ai","kind":"product","brief":null}]
